INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Sicherheitsmethode immer eine Risikoanalyse braucht?', 2, '[{"text": "Nein", "correct": true, "because": "Pauschale Gefährdungen genügen"}, {"text": "Ja", "correct": false, "because": "Nur bei erhöhtem Bedarf"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Baustein hilft dir, Sicherheitsmanagement zu organisieren?', 3, '[{"text": "ISMS", "correct": true, "because": "Definiert Prozesse"}, {"text": "APP", "correct": false, "because": "Anwendungen"}, {"text": "NET", "correct": false, "because": "Netzwerke"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bereiche deckt eine Methode zur Informationssicherheit ab?', 5, '[{"text": "Technische Maßnahmen", "correct": true, "because": "Schützt Systeme"}, {"text": "Organisatorische Aspekte", "correct": true, "because": "Regelt Abläufe"}, {"text": "Personelle Maßnahmen", "correct": true, "because": "Schult Mitarbeiter"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Es gibt Basis-Absicherung für Einsteiger. b) Sie ersetzt Datenschutz.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Datenschutz separat"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was übersehst du, wenn du ein Sicherheitskonzept erstellst?', 4, '[{"text": "Gefährdungsanalyse", "correct": false, "because": "Basis der Methode"}, {"text": "Bausteine", "correct": false, "because": "Definieren Maßnahmen"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine Sicherheitsmethode nur für große Firmen ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Für alle Größen geeignet"}, {"text": "Ja", "correct": false, "because": "Auch KMUs nutzen es"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorgehensweise hilft kleinen Unternehmen beim Einstieg?', 3, '[{"text": "Basis-Absicherung", "correct": true, "because": "Einfacher Start"}, {"text": "Kern-Absicherung", "correct": false, "because": "Für Teile"}, {"text": "Standard-Absicherung", "correct": false, "because": "Komplett"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine Sicherheitsmethode?', 5, '[{"text": "Strukturierter Schutz", "correct": true, "because": "Systematischer Ansatz"}, {"text": "Kosteneffizienz", "correct": true, "because": "Pauschale Maßnahmen"}, {"text": "ISO-Kompatibilität", "correct": true, "because": "Zertifizierbar"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) Bausteine Gefährdungen listen und b) sie nur für Server gelten. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Für alle Systeme"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauchst du nicht, um ein Sicherheitsniveau zu erhöhen?', 4, '[{"text": "Kompendium", "correct": false, "because": "Enthält Maßnahmen"}, {"text": "Standards", "correct": false, "because": "Definieren Vorgehen"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist eine Zertifizierung Pflicht?', 2, '[{"text": "Nein", "correct": true, "because": "Freiwillig"}, {"text": "Ja", "correct": false, "because": "Optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte gehören zur Basis-Absicherung?', 4, '[{"text": "Gefährdungen prüfen", "correct": true, "because": "Erster Schritt"}, {"text": "Maßnahmen umsetzen", "correct": true, "because": "Grundschutz"}, {"text": "Webdesign", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine Methode nur Technik abdeckt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Organisation"}, {"text": "Ja", "correct": false, "because": "Ganzheitlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgst du mit einer Sicherheitsmethode?', 3, '[{"text": "Schutz erhöhen", "correct": true, "because": "Informationssicherheit"}, {"text": "Kosten senken", "correct": false, "because": "Indirekt"}, {"text": "Design verbessern", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Es nutzt pauschale Gefährdungen. b) Es ist nur für Behörden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Unternehmen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielen Bausteine?', 4, '[{"text": "Maßnahmen definieren", "correct": true, "because": "Strukturieren Schutz"}, {"text": "Daten komprimieren", "correct": false, "because": "Anderer Zweck"}, {"text": "Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Methode für KMUs geeignet ist?', 2, '[{"text": "Ja", "correct": true, "because": "Basis-Absicherung"}, {"text": "Nein", "correct": false, "because": "Für alle Größen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen eine Sicherheitsmethode effektiv?', 5, '[{"text": "Ganzheitlichkeit", "correct": true, "because": "Alle Bereiche"}, {"text": "Pragmatismus", "correct": true, "because": "Einfache Umsetzung"}, {"text": "Standards", "correct": true, "because": "Nachvollziehbar"}, {"text": "Hohe Kosten", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ersetzt sie ISO 27001?', 3, '[{"text": "Nein", "correct": true, "because": "Kompatibel, nicht identisch"}, {"text": "Ja", "correct": false, "because": "Ergänzt ISO"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu einer Sicherheitsmethode?', 4, '[{"text": "Firewall für kleines Büro", "correct": true, "because": "Basis-Absicherung"}, {"text": "Webdesign erstellen", "correct": false, "because": "Anderer Zweck"}, {"text": "Daten komprimieren", "correct": false, "because": "Irrelevant"}]');
